请对以下 case 进行三维加权评分。

=== case_id ===
Case-23-countdown-018

=== 用户原始指令 (query.txt) ===
结婚纪念日卡片要改改,左边深色块分区主题色,右边浅色块分区,中间一个环形进度条显示已经走过的百分比,旁边写"携手走过的XX%"这种动态拼接,点圆形能跳到系统显示设置,夜晚蓝紫渐变,纯文字色块不要图,数据从日历读,标个"已达成"状态。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "结婚纪念日卡片要改改,左边深色块分区主题色,右边浅色块分区,中间一个环形进度条显示已经走过的百分比,旁边写\"携手走过的XX%\"这种动态拼接,点圆形能跳到系统显示设置,夜晚蓝紫渐变,纯文字色块不要图,数据从日历读,标个\"已达成\"状态。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "display_settings"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "calendar": {
        "items": [
          {
            "entityName": {
              "type": "string",
              "description": "日历事件类别",
              "sampleValue": "calendar"
            },
            "entityId": {
              "type": "string",
              "description": "日历事件唯一标识",
              "sampleValue": "anniversary-001"
            },
            "title": {
              "type": "string",
              "description": "纪念日日程标题",
              "sampleValue": "结婚纪念日"
            },
            "dtStart": {
              "type": "string",
              "description": "纪念日起始日期展示文本",
              "sampleValue": "2016.07.09"
            },
            "dtEnd": {
              "type": "string",
              "description": "纪念日结束日期展示文本",
              "sampleValue": "2016.07.09"
            },
            "description": {
              "type": "string",
              "description": "纪念日辅助说明",
              "sampleValue": "十周年纪念"
            }
          }
        ]
      }
    },
    "view": {
      "progressPercent": {
        "type": "number",
        "description": "根据日历纪念日计算出的已走过百分比数值",
        "sampleValue": 73
      },
      "progressTotal": {
        "type": "number",
        "description": "进度百分比总量",
        "sampleValue": 100
      },
      "progressText": {
        "type": "string",
        "description": "已走过百分比展示文本",
        "sampleValue": "73%"
      },
      "statusText": {
        "type": "string",
        "description": "纪念日目标状态",
        "sampleValue": "已达成"
      }
    }
  },
  "assetCandidates": []
}

